<script setup lang="ts">
import {ref,watch,onMounted} from 'vue'
import {IconX,IconPlus,IconCheck} from '@tabler/icons-vue'
import type {WikiApi,WikiTreeView} from './api'
const props=defineProps<{api:WikiApi;tree:WikiTreeView;ru:boolean}>()
const dialog=ref<HTMLDialogElement|null>(null)
onMounted(()=>dialog.value?.showModal())
const emit=defineEmits<{changed:[];close:[]}>()
const uid=ref(''),title=ref(''),description=ref(''),parent=ref(''),order=ref(0),version=ref<number|null>(null),treeVersion=ref(props.tree.version),busy=ref(false),error=ref('')
watch(uid,id=>{const s=props.tree.sections.find(s=>s.uid===id);title.value=s?.title??'';description.value=s?.description??'';parent.value=s?.parent_uid??'';order.value=s?.sort_order??0;version.value=s?.version??null;treeVersion.value=props.tree.version;error.value=''}, {immediate:true})
async function save(remove=false){if(busy.value)return;busy.value=true;error.value='';try{if(remove&&uid.value&&version.value)await props.api.deleteSection(uid.value,version.value,treeVersion.value);else await props.api.saveSection(uid.value||null,{title:title.value,description:description.value,parent_uid:parent.value||null,sort_order:order.value,expected_version:version.value,expected_tree_version:treeVersion.value});emit('changed');emit('close')}catch(e){error.value=e instanceof Error?e.message:'UNAVAILABLE'}finally{busy.value=false}}
</script>
<template>
 <dialog ref="dialog" @cancel="busy?$event.preventDefault():emit('close')" :aria-label="ru?'Управление разделами':'Manage sections'" class="wiki-sections-modal" @keydown.esc="emit('close')"><header><h2>{{ru?'Разделы библиотеки':'Library sections'}}</h2><button class="icon-button" :disabled="busy" :aria-label="ru?'Закрыть':'Close'" @click="emit('close')"><IconX :size="20"/></button></header><form @submit.prevent="save()"><fieldset :disabled="busy" class="wiki-editor-fields"><label>{{ru?'Раздел':'Section'}}<select v-model="uid" autofocus><option value="">＋ {{ru?'Новый раздел':'New section'}}</option><option v-for="s in tree.sections" :key="s.uid" :value="s.uid">{{s.title}}</option></select></label><label>{{ru?'Название':'Title'}}<input v-model="title" required maxlength="160"></label><label>{{ru?'Описание':'Description'}}<textarea v-model="description" rows="2" maxlength="600"/></label><div class="wiki-form-row"><label>{{ru?'Родительский раздел':'Parent section'}}<select v-model="parent"><option value="">{{ru?'В корне':'Root'}}</option><option v-for="s in tree.sections.filter(s=>s.uid!==uid)" :key="s.uid" :value="s.uid">{{s.title}}</option></select></label><label>{{ru?'Порядок':'Order'}}<input v-model.number="order" type="number" min="0" max="1000000" required></label></div></fieldset><p v-if="error" role="alert">{{error==='SECTION_IN_USE'?(ru?'Раздел содержит страницы, подразделы или историю редакций.':'Section contains pages, child sections or revision history.'):error==='VERSION_CONFLICT'?(ru?'Дерево изменилось. Закройте окно и обновите библиотеку.':'The tree changed. Close and refresh the library.'):(ru?'Не удалось сохранить: проверьте родителя, глубину и права.':'Could not save: check parent, depth and access.')}}</p><footer class="wiki-editor-actions"><button :disabled="busy||!title.trim()"><IconCheck :size="17"/>{{ru?'Сохранить':'Save'}}</button><button v-if="uid" type="button" :disabled="busy" @click="save(true)">{{ru?'Удалить пустой раздел':'Delete empty section'}}</button><button v-else type="button" @click="uid='';title='';description='';parent='';order=0"><IconPlus :size="17"/>{{ru?'Очистить':'Clear'}}</button></footer></form></dialog>
</template>
